using System;
using System.IO;
using System.Collections.Generic;
using System.Diagnostics;
using System.Web.Script.Serialization;
namespace RotaAvalon {
    public static class SelfTest {
        static System.Windows.Forms.TabControl FindTabs(System.Windows.Forms.Control root){if(root is System.Windows.Forms.TabControl)return (System.Windows.Forms.TabControl)root;foreach(System.Windows.Forms.Control child in root.Controls){var result=FindTabs(child);if(result!=null)return result;}return null;}
        static void Check(bool value,string message){if(!value)throw new Exception(message);}
        static void CheckListHandles(System.Windows.Forms.Control root){if(root is System.Windows.Forms.ListView){var handle=root.Handle;Check(handle!=IntPtr.Zero,"Lista sem handle nativo");}foreach(System.Windows.Forms.Control child in root.Controls)CheckListHandles(child);}
        public static int Run(bool readGame=false){
            string directory=Path.Combine(Path.GetTempPath(),"RotaAvalon-Test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);
            try {
                var r=new RouteDocument{Name="Rota de teste",Character="Teste"};r.Points.Add(new Waypoint{X=0,Y=0,Z=0});r.Points.Add(new Waypoint{X=3,Y=0,Z=4,Action="Coletar",WaitMs=1500});
                Check(r.FlightHeight==60&&r.RewardOption==2,"Altura ou segunda opção de recompensa incorretas");r.FlightHeight=73;r.Region="Fei Wei";r.SearchRadius=1500;
                r.ResourceIds.Add(3092);r.Points[1].ResourceId=3092;r.Points[1].ItemId=62505;
                Check(Math.Abs(r.Length()-5)<0.00001,"Distância incorreta");r.Loop=true;Check(Math.Abs(r.Length()-10)<0.00001,"Fechamento circular incorreto");
                string file=Path.Combine(directory,"rota.json");r.Save(file);var loaded=RouteDocument.Load(file);Check(loaded.Points.Count==2&&loaded.Points[1].Action=="Coletar"&&loaded.Points[1].WaitMs==1500,"Roundtrip perdeu dados");
                Check(loaded.ResourceIds.Count==1&&loaded.ResourceIds[0]==3092&&loaded.Points[1].ResourceId==3092&&loaded.Points[1].ItemId==62505,"Seleção de materiais perdida ao salvar");Check(loaded.FlightHeight==73&&loaded.Region=="Fei Wei"&&loaded.SearchRadius==1500,"Configuração de busca/voo perdida ao salvar");
                string legacy=Path.Combine(directory,"antiga.json");File.WriteAllText(legacy,"{\"Schema\":1,\"Name\":\"Antiga\",\"ClientHash\":\""+GameClient.SupportedHash+"\",\"Character\":\"\",\"Points\":[]}");Check(RouteDocument.Load(legacy).ResourceIds.Count==0,"Rota antiga não foi carregada");
                Check(RouteDocument.Load(legacy).FlightHeight==60&&RouteDocument.Load(legacy).RewardOption==2&&RouteDocument.Load(legacy).SearchRadius==1000,"Padrões de rota antiga incorretos");
                Check(GameActivity.Classify(".?AVCECHPWorkTrace@@",0)==ActivityKind.Approaching&&GameActivity.Classify(".?AVCECHPWorkPick@@",3537)==ActivityKind.Collecting&&GameActivity.Classify(".?AVCECHPWorkPick@@",0)==ActivityKind.Other,"Classificação de aproximação/coleta incorreta");
                Check(VerifiedRewards.Find(3537).FinalItemId==1850&&VerifiedRewards.Find(3539).FinalItemId==1821&&VerifiedRewards.Find(3546)==null,"Recompensa não validada foi aceita");
                var bag=new InventorySnapshot();bag.Items.Add(new InventoryItem{Id=815,Quantity=3});bag.Items.Add(new InventoryItem{Id=815,Quantity=7});bag.Items.Add(new InventoryItem{Id=62502,Quantity=1});Check(bag.QuantityOf(815)==10&&bag.QuantityOf(62502)==1&&bag.QuantityOf(999)==0,"Inventário confundiu item temporário ou pilhas");
                loaded.Name="Sobrescrita";loaded.Save(file);Check(RouteDocument.Load(file).Name=="Sobrescrita","Salvamento atômico falhou");
                loaded.Points[0].X=Double.NaN;bool failed=false;try{loaded.Validate();}catch(InvalidDataException){failed=true;}Check(failed,"NaN foi aceito");
                loaded.Points[0].X=0;loaded.ClientHash="outro";failed=false;try{loaded.Validate();}catch(InvalidDataException){failed=true;}Check(failed,"Perfil incompatível foi aceito");
                Console.WriteLine("PASS: distâncias, circuito, serialização, substituição, altura persistida e pilhas do inventário.");
                var transform=new MapTransform{CenterX=-1388,CenterZ=795,Scale=2,Width=800,Height=600};var center=transform.Screen(-1388,795);Check(center.X==400&&center.Y==300,"Centro do mapa incorreto");var north=transform.Screen(-1388,805);Check(north.Y<center.Y,"Norte invertido");var roundtrip=transform.World(center.X,center.Y);Check(roundtrip.X==-1388&&roundtrip.Y==795,"Projeção inversa incorreta");Check(MapTransform.TileColumn(-1388)==5&&MapTransform.TileRow(795)==9,"Bloco do terreno incorreto");
                var catalog=ResourceCatalog.LoadEmbedded();Check(catalog.Definitions.Count==1523&&catalog.Definitions[3092].item1Id==62505,"Catálogo incorreto");Check(!String.IsNullOrWhiteSpace(catalog.Definitions[3079].icone),"Ícone de ferro ausente");Console.WriteLine("PASS: rotas antigas, seleção de materiais, catálogo e projeção do terreno.");
                string cache=Path.Combine(directory,"historico.json");var history=new ResourceHistory(cache,catalog);var observer=new ClientSnapshot{Level=87,X=0,Y=0,Z=0};var frameTest=new ResourceFrame{Terrain=new TerrainBounds{Left=-4096,Right=4096,Top=5632,Bottom=-5632}};
                frameTest.Resources.Add(new ResourceMarker{InstanceId=1,TemplateId=3076,X=10,Y=0,Z=0});frameTest.Resources.Add(new ResourceMarker{InstanceId=2,TemplateId=3076,X=50,Y=0,Z=0});
                Check(history.Merge(observer,frameTest).Count==2,"Histórico colapsou ocorrências distintas do mesmo material");frameTest.Resources[0].X=12;Check(history.Merge(observer,frameTest).Count==2,"Pequeno deslocamento duplicou um local");frameTest.Resources.Clear();var absent=history.Merge(observer,frameTest);Check(absent.Count==2&&absent.TrueForAll(v=>v.Historical),"Locais ausentes sumiram ou foram tratados como vivos");history.Save();Check(new ResourceHistory(cache,catalog).Merge(observer,frameTest).Count==2,"Histórico não persistiu");
                Check(RouteExecution.MissionFor(3076)==61532&&RouteExecution.MissionFor(3091)==61547&&RouteExecution.MissionFor(3546)==62002&&RouteExecution.MissionFor(4308)==0,"Execução aceitou missão sem identificação validada");Console.WriteLine("PASS: histórico persistente, repetição de materiais e distinção de pontos ausentes.");
                var clustered=new ResourceHistory(Path.Combine(directory,"aglomerados.json"),catalog);frameTest.Resources.Add(new ResourceMarker{InstanceId=10,TemplateId=3076,X=10,Y=0,Z=0});frameTest.Resources.Add(new ResourceMarker{InstanceId=11,TemplateId=3076,X=11,Y=0,Z=0});Check(clustered.Merge(observer,frameTest).Count==2,"Duas instâncias próximas foram unificadas no histórico");
                var survey=RegionSurvey.Plan(new System.Drawing.RectangleF(-240,-120,480,240),observer);Check(!survey.Loop&&survey.Points.Count==15,"Grade de mapeamento inválida");foreach(var p in survey.Points)Check(p.X>=-240&&p.X<=240&&p.Z>=-120&&p.Z<=120&&p.Action=="Passar","Mapeamento saiu da área ou tentou coletar");for(int i=1;i<survey.Points.Count;i++)Check(survey.Points[i].DistanceTo(survey.Points[i-1])<=120.001,"Faixa de mapeamento deixou intervalo excessivo");bool tooLarge=false;try{RegionSurvey.Plan(new System.Drawing.RectangleF(-4000,-5000,8000,10000),observer);}catch(ArgumentException){tooLarge=true;}Check(tooLarge,"Mapeamento excessivo não foi limitado");Console.WriteLine("PASS: ocorrências vizinhas separadas e varredura da área visível.");
                using(var form=new RotaForm(true)){var tabs=FindTabs(form);Check(tabs!=null&&tabs.TabPages.Count==4,"Aba de mapa ausente");Check(tabs.SelectedTab.Text=="Farm","Aba inicial incorreta");CheckListHandles(form);}Console.WriteLine("PASS: construção da interface, listas nativas e aba de mapa selecionada.");
                var verified=new Dictionary<string,bool>(StringComparer.OrdinalIgnoreCase);int clients=0;
                foreach(var p in readGame?Process.GetProcessesByName("ElementClient"):new Process[0]){using(var client=new GameClient(p.Id,verified)){var s=client.Read();var activity=client.ReadActivity();var inventory=client.ReadInventory();Check(activity.Actions.Count<=256&&inventory.Slots>0,"Ações/inventário indisponíveis");Console.WriteLine("PASS: ações nativas e inventário do cliente real.");Check(s.Pid==p.Id&&s.Level>0,"Telemetria inválida");var frame=client.ReadResources(catalog,s);var unique=new HashSet<uint>();foreach(var resource in frame.Resources){Check(unique.Add(resource.InstanceId),"Instância de material duplicada");Check(catalog.Definitions.ContainsKey(resource.TemplateId)&&resource.Distance>=0,"Marcador inválido");}Console.WriteLine(new JavaScriptSerializer().Serialize(new {pid=s.Pid,name=s.Name,level=s.Level,x=s.X,y=s.Y,z=s.Z,resources=frame.Resources}));using(var tiles=new MapTiles(client.GameDirectory)){using(var icon=tiles.Image(catalog.Definitions[3079].icone))Check(icon!=null,"Ícone real do ferro não carregou");for(int row=0;row<22;row++)for(int col=0;col<16;col++){var tile=tiles.Tile(row,col);Check(tile!=null&&tile.Width==256&&tile.Height==256,"Bloco de terreno inválido");}Check(tiles.Tile(0,0)!=null,"Cache não recuperou bloco descartado");}Console.WriteLine("PASS: instâncias próximas, ícone real e 352 blocos do minimapa.");clients++;}p.Dispose();}
                Console.WriteLine(clients>0?"PASS: leitura real de "+clients+" cliente(s).":"SKIP: nenhum cliente visível neste contexto.");return 0;
            }catch(Exception e){Console.Error.WriteLine("FAIL: "+e);return 1;}
            finally {foreach(var file in Directory.GetFiles(directory))File.Delete(file);Directory.Delete(directory);}
        }
    }
}


